 "new_string": "from src.billing.tax import invoice_tax, line_total, tax_for


def test_line_total():
    assert line_total([{"quantity": 2, "unit_cents": 150}]) == 300


def test_tax_for_uses_bankers_rounding():
    assert tax_for(50, "0.05") == 2  # 2.5 -> 2
    assert tax_for(70, "0.05") == 4  # 3.5 -> 4


def test_invoice_tax_rounds_per_line():
    lines = [{"quantity": 1, "unit_cents": 50}, {"quantity": 1, "unit_cents": 50}]
    # Per line: 2.5 -> 2, twice = 4. Rounding the total (5.0) would give 5.
    assert invoice_tax(lines, "0.05") == 4


def test_invoice_tax_accepts_float_rate():
    assert invoice_tax([{"quantity": 3, "unit_cents": 1000}], 0.07) == 210


def test_invoice_tax_empty():
    assert invoice_tax([], "0.05") == 0"
